window.GUIDE={"cats": {"sights": {"sec": "see", "title": "Sights & oddities", "emoji": "🏰", "color": "#C0392B"}, "galleries": {"sec": "see", "title": "Galleries", "emoji": "🎨", "color": "#8E44C9"}, "shops": {"sec": "see", "title": "Indie shops & makers", "emoji": "🛍️", "color": "#E8930C"}, "records": {"sec": "see", "title": "Records, books & comics", "emoji": "📀", "color": "#1877D0"}, "vintage": {"sec": "see", "title": "Vintage & antiques", "emoji": "🧥", "color": "#0F766E"}, "gear": {"sec": "see", "title": "Cameras, music & tech", "emoji": "📷", "color": "#0E7490"}, "food": {"sec": "see", "title": "Food shops & world grocers", "emoji": "🧀", "color": "#B45309"}, "fun": {"sec": "see", "title": "Escape rooms & things to do", "emoji": "🧩", "color": "#DB2777"}, "fashion": {"sec": "see", "title": "Clothes & boutiques", "emoji": "👗", "color": "#9D174D"}, "charity": {"sec": "see", "title": "Charity shops", "emoji": "♻️", "color": "#15803D"}, "parks": {"sec": "see", "title": "Parks & walks", "emoji": "🌳", "color": "#2F855A"}, "trips": {"sec": "see", "title": "Day trips", "emoji": "🚗", "color": "#1D4ED8"}, "cafes": {"sec": "eat", "title": "Cafés & coffee", "emoji": "☕", "color": "#0F9D8A"}, "cheap": {"sec": "eat", "title": "Cheap eats & street food", "emoji": "🌮", "color": "#E8483B"}, "mid": {"sec": "eat", "title": "Mid-range", "emoji": "🍽️", "color": "#E8930C"}, "splurge": {"sec": "eat", "title": "Splurge & Michelin", "emoji": "⭐", "color": "#8E44C9"}, "pubs": {"sec": "eat", "title": "Historic & real-ale pubs", "emoji": "🍺", "color": "#A0522D"}, "bars": {"sec": "eat", "title": "Cocktails & craft bars", "emoji": "🍸", "color": "#1877D0"}, "music": {"sec": "eat", "title": "Live music & comedy", "emoji": "🎸", "color": "#7C3AED"}}, "items": [{"id": "n1", "cat": "sights", "name": "City of Caves", "addr": "Garner's Hill steps, Sussex Street / Cliff Road, NG1 1HF", "text": "Nottingham sits on soft sandstone riddled with more than 800 man-made caves. This guided tour takes you through medieval tannery pits, a WWII air-raid shelter and Victorian slum cellars right under the city centre. Tours run about every 30–45 minutes and take around an hour.", "tip": "Entrance at the foot of the Garner's Hill steps, by Nottingham Contemporary · now run by the National Justice Museum", "lat": 52.950294, "lon": -1.146042, "price": 0, "walk": 7, "img": "img/n1.svg", "q": "City of Caves, Garner's Hill steps, Sussex Street / Cliff Road, NG1 1HF, Nottingham", "ta": true, "far": false, "web": "https://nationaljusticemuseum.org.uk/cityofcaves", "drive": "", "who": []}, {"id": "n2", "cat": "sights", "name": "National Justice Museum", "addr": "Shire Hall, High Pavement, NG1 1HN", "text": "A Victorian courthouse and county gaol in the Lace Market, where you can stand in the dock, see the cells and the execution yard, and hear the grim stories of people tried here. Actors in costume bring the courtroom to life on some days.", "tip": "Allow 2 hours; good on a rainy day", "lat": 52.95071, "lon": -1.144218, "price": 0, "walk": 8, "img": "img/n2.svg", "q": "National Justice Museum, Shire Hall, High Pavement, NG1 1HN, Nottingham", "ta": true, "far": false, "web": "https://www.nationaljusticemuseum.org.uk", "drive": "", "who": []}, {"id": "n3", "cat": "sights", "name": "Nottingham Castle", "addr": "Lenton Road, NG1 6EL", "text": "Not a medieval castle but a 17th-century ducal mansion on top of Castle Rock, rebuilt after rioters burned it in 1831. Inside: the city's art collection, lace galleries and the Robin Hood story; underneath, Mortimer's Hole and other caves. Free grounds views over the city.", "tip": "Check opening and cave tour times before you go", "lat": 52.9495, "lon": -1.15468, "price": 0, "walk": 9, "img": "img/n3.svg", "q": "Nottingham Castle, Lenton Road, NG1 6EL, Nottingham", "ta": true, "far": false, "web": "https://www.nottinghamcastle.org.uk", "drive": "", "who": []}, {"id": "n4", "cat": "sights", "name": "Park Tunnel", "addr": "Derby Road entrance by Canning Circus, NG7 1", "text": "A tunnel cut through the sandstone in 1855 as a carriage entrance to The Park, the private Victorian estate of grand villas below the Castle. It was never used for carriages because the slope was too steep. Now a free, atmospheric footpath with an open-air light well in the middle.", "tip": "Walk down from Derby Road into The Park", "lat": 52.954165, "lon": -1.159836, "price": 0, "walk": 11, "img": "img/n4.svg", "q": "Park Tunnel, Derby Road entrance by Canning Circus, NG7 1, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n5", "cat": "sights", "name": "Old Market Square & the Council House", "addr": "Old Market Square, NG1 2DT", "text": "The UK's second-largest civic square, overlooked by the 1929 Council House with its dome and two stone lions. 'Meet you by the left lion' is the classic local rendezvous, and gave the city's culture magazine its name. The Exchange Arcade inside the Council House has a painted dome.", "tip": "Christmas market and ice rink here every winter", "lat": 52.953424, "lon": -1.148611, "price": 0, "walk": 1, "img": "img/n5.svg", "q": "Old Market Square & the Council House, Old Market Square, NG1 2DT, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n6", "cat": "sights", "name": "Lace Market & St Mary's Church", "addr": "High Pavement, NG1 1HF", "text": "The medieval heart of Nottingham, rebuilt in the 1800s as a canyon of tall red-brick lace warehouses and showrooms. St Mary's is the city's oldest church, a 15th-century Perpendicular giant with fine stained glass. The Adams Building on Stoney Street was built with a chapel and library for its workers.", "tip": "Wander Stoney St, Broadway and St Mary's Gate", "lat": 52.951187, "lon": -1.143048, "price": 0, "walk": 8, "img": "img/n6.svg", "q": "Lace Market & St Mary's Church, High Pavement, NG1 1HF, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n7", "cat": "sights", "name": "Robin Hood statue", "addr": "Castle Road, NG1 6AA", "text": "The bronze outlaw by James Woodford, unveiled in 1952 below the Castle walls. His arrow has been stolen so many times it's a running joke. Every visitor gets the photo.", "tip": "Quick photo stop on the way to the Trip", "lat": 52.9506, "lon": -1.152, "price": 0, "walk": 5, "img": "img/n7.svg", "q": "Robin Hood statue, Castle Road, NG1 6AA, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n8", "cat": "sights", "name": "Green's Windmill", "addr": "Windmill Lane, Sneinton, NG2 4QB", "text": "A tower windmill in Sneinton, once owned by the mathematician George Green, whose work underpins modern physics. It has been under major repair, with the mill closed to visitors, but the small science centre tells Green's story.", "tip": "Repairs were due to finish in November 2026; check before you go", "lat": 52.952098, "lon": -1.129386, "price": 0, "walk": 22, "img": "img/n8.svg", "q": "Green's Windmill, Windmill Lane, Sneinton, NG2 4QB, Nottingham", "ta": true, "far": false, "web": "https://www.greensmill.org.uk", "drive": "", "who": []}, {"id": "n9", "cat": "sights", "name": "The Arboretum", "addr": "Waverley Street, NG7 4HF", "text": "Nottingham's first public park, opened in 1852: a hilly Victorian garden with a pagoda, bandstand, aviary and Crimean War cannons. Quiet, free and a short walk north of the centre.", "tip": "Pair with Mansfield Road pubs", "lat": 52.959801, "lon": -1.157383, "price": 0, "walk": 14, "img": "img/n9.svg", "q": "The Arboretum, Waverley Street, NG7 4HF, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n10", "cat": "sights", "name": "Theatre Royal & Royal Concert Hall", "addr": "Theatre Square, NG1 5ND", "text": "The 1865 Theatre Royal with its six Corinthian columns, joined to the modern Royal Concert Hall. Touring West End shows, panto, comedy and big concerts. Even if you're not going in, the portico lit at night is one of the city's best sights.", "tip": "Panto season runs through December", "lat": 52.955697, "lon": -1.151785, "price": 0, "walk": 5, "img": "img/n10.svg", "q": "Theatre Royal & Royal Concert Hall, Theatre Square, NG1 5ND, Nottingham", "ta": true, "far": false, "web": "https://trch.co.uk", "drive": "", "who": []}, {"id": "n11", "cat": "sights", "name": "Broadway Cinema", "addr": "14–18 Broad Street, NG1 3AL", "text": "The city's independent cinema in a former Methodist chapel in Hockley, showing art-house, world and classic film. Its café-bar is open to everyone and is one of Hockley's best meeting spots. A room here was designed by Paul Smith.", "tip": "Drop in for a drink even without a ticket", "lat": 52.954306, "lon": -1.143663, "price": 0, "walk": 7, "img": "img/n11.svg", "q": "Broadway Cinema, 14–18 Broad Street, NG1 3AL, Nottingham", "ta": true, "far": false, "web": "https://www.broadway.org.uk", "drive": "", "who": []}, {"id": "n12", "cat": "sights", "name": "Wollaton Hall & Deer Park", "addr": "Wollaton Park, NG8 2AE", "text": "A spectacular Elizabethan prodigy house, built in the 1580s, set in a 500-acre park with free-roaming red and fallow deer. It was Wayne Manor in The Dark Knight Rises. The natural history museum inside is free; parking is paid.", "tip": "Drive or bus 30; allow half a day", "lat": 52.94796, "lon": -1.209771, "price": 0, "walk": 66, "img": "img/n12.svg", "q": "Wollaton Hall & Deer Park, Wollaton Park, NG8 2AE, Nottingham", "ta": true, "far": true, "web": "", "drive": "", "who": []}, {"id": "n13", "cat": "galleries", "name": "Nottingham Contemporary", "addr": "Weekday Cross, NG1 2GB", "text": "One of the UK's largest contemporary art centres, in a building wrapped in concrete panels cast from a Victorian lace pattern. Four free galleries, a strong bookshop and a café, right on the edge of the Lace Market. 2026 includes the first institutional solo show of the late British artist Sarah Cunningham.", "tip": "Free · closed Mondays", "lat": 52.951048, "lon": -1.145929, "price": 0, "walk": 6, "img": "img/n13.svg", "q": "Nottingham Contemporary, Weekday Cross, NG1 2GB, Nottingham", "ta": true, "far": false, "web": "https://www.nottinghamcontemporary.org", "drive": "", "who": []}, {"id": "n14", "cat": "galleries", "name": "Surface Gallery", "addr": "16 Southwell Road, NG1 1DL", "text": "A volunteer-led, artist-run contemporary gallery run as a co-operative by early-career artists. Ambitious, rough-edged shows, open calls and an annual street art festival.", "tip": "Opens around exhibitions; check dates", "lat": 52.953293, "lon": -1.137724, "price": 0, "walk": 13, "img": "img/n14.svg", "q": "Surface Gallery, 16 Southwell Road, NG1 1DL, Nottingham", "ta": false, "far": false, "web": "https://www.surfacegallery.org", "drive": "", "who": []}, {"id": "n15", "cat": "galleries", "name": "BACKLIT", "addr": "Alfred House, Ashley Street, NG3 1JG", "text": "An independent artist-led space founded in 2008, with galleries across three floors of an 1872 Victorian building in Sneinton, plus studios. A new ground-floor gallery and People's Archive opened through 2026. Its 'Our Marian' sculpture now stands at Tollhouse Hill.", "tip": "Open during exhibitions; check online", "lat": 52.95568, "lon": -1.13568, "price": 0, "walk": 16, "img": "img/n15.svg", "q": "BACKLIT, Alfred House, Ashley Street, NG3 1JG, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n16", "cat": "galleries", "name": "New Art Exchange", "addr": "39–41 Gregory Boulevard, Hyson Green, NG7 6BE", "text": "The UK's largest gallery dedicated to culturally diverse contemporary art, in the heart of Hyson Green. Free exhibitions, a café, and Radford Road's food shops on the doorstep.", "tip": "Tram to Hyson Green Market", "lat": 52.96595, "lon": -1.168443, "price": 0, "walk": 31, "img": "img/n16.svg", "q": "New Art Exchange, 39–41 Gregory Boulevard, Hyson Green, NG7 6BE, Nottingham", "ta": true, "far": true, "web": "https://www.nae.org.uk", "drive": "", "who": []}, {"id": "n17", "cat": "galleries", "name": "Primary", "addr": "33 Seely Road, Lenton, NG7 1NU", "text": "A former Victorian primary school, now artists' studios with a public programme of exhibitions, talks and events. A real look inside the city's artist community.", "tip": "Best on open days and event nights", "lat": 52.95531, "lon": -1.1677, "price": 0, "walk": 20, "img": "img/n17.svg", "q": "Primary, 33 Seely Road, Lenton, NG7 1NU, Nottingham", "ta": false, "far": false, "web": "https://www.weareprimary.org", "drive": "", "who": []}, {"id": "n18", "cat": "galleries", "name": "Bonington Gallery", "addr": "Bonington Building, Dryden Street, NG1 4FZ", "text": "Nottingham Trent University's free gallery in its brutalist art-school building. Thoughtful, often experimental contemporary exhibitions and rarely crowded.", "tip": "Term-time programme", "lat": 52.95827, "lon": -1.15321, "price": 0, "walk": 10, "img": "img/n18.svg", "q": "Bonington Gallery, Bonington Building, Dryden Street, NG1 4FZ, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n19", "cat": "galleries", "name": "Fletcher Gate Fine Art Gallery", "addr": "18 Fletcher Gate, Lace Market, NG1 2FZ", "text": "Also known as the Fletcher Gate Art Gallery. An independent gallery for original fine art for sale, from local and national artists, in the Lace Market. A relaxed place to browse paintings you could actually take home.", "tip": "Thu–Sun 11:00–16:00", "lat": 52.953, "lon": -1.1458, "price": 0, "walk": 4, "img": "img/n19.svg", "q": "Fletcher Gate Fine Art Gallery, 18 Fletcher Gate, Lace Market, NG1 2FZ, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n20", "cat": "galleries", "name": "Nottingham Society of Artists", "addr": "61 Friar Lane, NG1 6DA", "text": "Founded in 1880, the society runs its own gallery behind an unassuming door on Friar Lane. Rolling exhibitions of members' work, often very affordable.", "tip": "Combine with the Castle", "lat": 52.951389, "lon": -1.152897, "price": 0, "walk": 5, "img": "img/n20.svg", "q": "Nottingham Society of Artists, 61 Friar Lane, NG1 6DA, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n21", "cat": "galleries", "name": "Djanogly Gallery, Lakeside Arts", "addr": "University Park, NG7 2RD", "text": "The University of Nottingham's arts centre beside the Highfields lake, with a gallery of historic and modern shows, plus theatre and music. A lovely place for a lakeside walk.", "tip": "Tram to University of Nottingham", "lat": 52.9393, "lon": -1.1886, "price": 0, "walk": 49, "img": "img/n21.svg", "q": "Djanogly Gallery, Lakeside Arts, University Park, NG7 2RD, Nottingham", "ta": true, "far": true, "web": "https://www.lakesidearts.org.uk", "drive": "", "who": []}, {"id": "n22", "cat": "galleries", "name": "Hooten Street Project", "addr": "Sneinton, NG3", "text": "A tiny space converted from part of an artist's studio, showing print and wall-based work by invited artists. Very small and occasional, which is the charm.", "tip": "Check dates before you go", "lat": 52.9552, "lon": -1.137, "price": 0, "walk": 14, "img": "img/n22.svg", "q": "Hooten Street Project, Sneinton, NG3, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n23", "cat": "galleries", "name": "Debbie Bryan", "addr": "1st floor, 4–6 St Peter's Gate, NG1 2JG", "text": "An award-winning independent creative gallery, shop and tearoom run by a textile designer. Nottingham lace, local makers, prints and gifts, plus craft workshops you can book.", "tip": "Book a workshop for a creative afternoon", "lat": 52.95215, "lon": -1.1479, "price": 0, "walk": 3, "img": "img/n23.svg", "q": "Debbie Bryan, 1st floor, 4–6 St Peter's Gate, NG1 2JG, Nottingham", "ta": true, "far": false, "web": "https://www.debbiebryan.co.uk", "drive": "", "who": []}, {"id": "n24", "cat": "shops", "name": "Sneinton Market Avenues", "addr": "Avenue A–C, Sneinton Market, NG1 1DW", "text": "Rows of old wholesale-market units converted into tiny shops and studios for designers, makers, florists and creative businesses, with Bustler street food in the middle. The heart of the Creative Quarter's east side.", "tip": "Saturdays are best · market hall refurbishment from autumn 2026", "lat": 52.95474, "lon": -1.13791, "price": 0, "walk": 13, "img": "img/n24.svg", "q": "Sneinton Market Avenues, Sneinton Market, NG1 1DW, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n25", "cat": "shops", "name": "Cobden Chambers", "addr": "off Pelham Street, NG1 2ED", "text": "A hidden courtyard off Pelham Street, home to small independent shops, makers and cafés. Easy to walk straight past the entrance.", "tip": "Tenants change; peek in whenever you pass", "lat": 52.953902, "lon": -1.145813, "price": 0, "walk": 4, "img": "img/n25.svg", "q": "Cobden Chambers, Pelham Street, NG1 2ED, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n26", "cat": "shops", "name": "Hurts Yard", "addr": "Hurts Yard, NG1 6JD", "text": "A narrow Victorian alley between Upper Parliament Street and Long Row packed with independents: records, barbers, vintage, and newer food spots like Shio at Six Richmond House.", "tip": "Start at the Upper Parliament St end", "lat": 52.954279, "lon": -1.152431, "price": 0, "walk": 3, "img": "img/n26.svg", "q": "Hurts Yard, Hurts Yard, NG1 6JD, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n27", "cat": "shops", "name": "Flying Horse Walk", "addr": "Poultry, NG1 2HN", "text": "A shopping passage through a former 17th-century coaching inn, with timbered gables over the entrance. Small shops, 200 Degrees coffee and Bar Gigi.", "tip": "Good start to a shopping loop", "lat": 52.952802, "lon": -1.148582, "price": 0, "walk": 2, "img": "img/n27.svg", "q": "Flying Horse Walk, Poultry, NG1 2HN, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n28", "cat": "shops", "name": "Bridlesmith Gate & Bridlesmith Walk", "addr": "Bridlesmith Gate, NG1 2GR", "text": "Nottingham's old fashion street, still lined with independent boutiques alongside designer names, plus the tucked-away Bridlesmith Walk lane of small units.", "tip": "Walk it towards Hockley", "lat": 52.952122, "lon": -1.147159, "price": 0, "walk": 4, "img": "img/n28.svg", "q": "Bridlesmith Gate & Bridlesmith Walk, Bridlesmith Gate, NG1 2GR, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n29", "cat": "shops", "name": "West End Arcade", "addr": "Upper Parliament Street, NG1 6JR", "text": "A small arcade off Upper Parliament Street with independent fashion, gifts and cafés, near Hurts Yard and the Theatre Royal.", "tip": "Combine with Hurts Yard", "lat": 52.954322, "lon": -1.153294, "price": 0, "walk": 4, "img": "img/n29.svg", "q": "West End Arcade, Upper Parliament Street, NG1 6JR, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n30", "cat": "fashion", "name": "Paul Smith, Willoughby House", "addr": "20 Low Pavement, NG1 7DL", "text": "Sir Paul Smith is Nottingham born and opened his first tiny shop here in 1970. His flagship is a gorgeous Georgian townhouse on Low Pavement, worth seeing for the interiors and the eccentric displays.", "tip": "Look out for the quirky objects in the windows", "lat": 52.951322, "lon": -1.147393, "price": 0, "walk": 4, "img": "img/n30.svg", "q": "Paul Smith, Willoughby House, 20 Low Pavement, NG1 7DL, Nottingham", "ta": true, "far": false, "web": "https://www.paulsmith.com", "drive": "", "who": ["m", "w"]}, {"id": "n31", "cat": "shops", "name": "Delilah Fine Foods", "addr": "12 Victoria Street, NG1 2EX", "text": "A deli in a grand old banking hall: marble counters, a mezzanine café and a huge cheese counter. Buy Nottinghamshire Stilton, charcuterie and wine to take home in the car.", "tip": "Ask for Colston Bassett Stilton, made in Notts", "lat": 52.95312, "lon": -1.14644, "price": 0, "walk": 4, "img": "img/n31.svg", "q": "Delilah Fine Foods, 12 Victoria Street, NG1 2EX, Nottingham", "ta": true, "far": false, "web": "https://www.delilahfinefoods.co.uk", "drive": "", "who": []}, {"id": "n32", "cat": "shops", "name": "Victoria Centre Market", "addr": "Victoria Centre (upper level), NG1 3QN", "text": "The city's old indoor market above the shopping centre. The council began closing it in 2023 and only a handful of traders remain, so go for nostalgia rather than a full market. Rowland Emett's whimsical water clock was removed in May 2026 for refurbishment.", "tip": "Check what's still open before making a special trip", "lat": 52.956382, "lon": -1.146493, "price": 0, "walk": 7, "img": "img/n32.svg", "q": "Victoria Centre Market, Victoria Centre (upper level), NG1 3QN, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n33", "cat": "records", "name": "Rough Trade Nottingham", "addr": "5 Broad Street, Hockley, NG1 3AJ", "text": "New vinyl, books and zines on the ground floor, with a bar and a 150-capacity live room upstairs for in-store gigs. The anchor of Hockley's music scene.", "tip": "In-store sets are often free; check events", "lat": 52.953898, "lon": -1.144173, "price": 0, "walk": 6, "img": "img/n33.svg", "q": "Rough Trade Nottingham, 5 Broad Street, Hockley, NG1 3AJ, Nottingham", "ta": true, "far": false, "web": "https://www.roughtrade.com", "drive": "", "who": []}, {"id": "n34", "cat": "records", "name": "Rob's Records", "addr": "4–5 Hurts Yard, NG1 6JD", "text": "A crate-digger's institution: crammed racks of second-hand vinyl across every genre, in the Hurts Yard alley.", "tip": "Check @robsrecordsnottingham for hours", "lat": 52.9548, "lon": -1.1516, "price": 0, "walk": 3, "img": "img/n34.svg", "q": "Rob's Records, 4–5 Hurts Yard, NG1 6JD, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n35", "cat": "records", "name": "Five Leaves Bookshop", "addr": "14a Long Row, NG1 2DH", "text": "A radical, independent bookshop and publisher up a passage off Long Row. Strong on politics, poetry, local history, LGBTQ+ and small-press fiction, with regular author events.", "tip": "Their Nottingham history titles make great gifts", "lat": 52.954104, "lon": -1.148793, "price": 0, "walk": 2, "img": "img/n35.svg", "q": "Five Leaves Bookshop, 14a Long Row, NG1 2DH, Nottingham", "ta": true, "far": false, "web": "https://fiveleavesbookshop.co.uk", "drive": "", "who": []}, {"id": "n36", "cat": "records", "name": "Page 45", "addr": "9 Market Street, NG1 6HY", "text": "An award-winning comics and graphic novel shop, with handwritten staff reviews on half the shelves. Brilliant for beginners: tell them what novels you like and let them pick.", "tip": "Ask for a recommendation", "lat": 52.954121, "lon": -1.151488, "price": 0, "walk": 2, "img": "img/n36.svg", "q": "Page 45, 9 Market Street, NG1 6HY, Nottingham", "ta": true, "far": false, "web": "https://www.page45.com", "drive": "", "who": []}, {"id": "n37", "cat": "vintage", "name": "Hopkinsons Vintage & Antiques", "addr": "21 Station Street, NG2 3AJ", "text": "A huge multi-dealer vintage, antique and retro emporium in a former warehouse opposite the railway station. Furniture, homewares, clothes, militaria and odd curios over several floors.", "tip": "Allow at least an hour", "lat": 52.94782, "lon": -1.14614, "price": 0, "walk": 11, "img": "img/n37.svg", "q": "Hopkinsons Vintage & Antiques, 21 Station Street, NG2 3AJ, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n38", "cat": "vintage", "name": "Derby Road antiques & vintage strip", "addr": "Derby Road, NG1 5", "text": "The slope from the centre up to Canning Circus is lined with antique dealers, vintage furniture, guitar shops and odd specialists. A slow browse that ends at three good pubs.", "tip": "Walk up, lunch at the top, stroll down", "lat": 52.9545, "lon": -1.159, "price": 0, "walk": 10, "img": "img/n38.svg", "q": "Derby Road antiques & vintage strip, Derby Road, NG1 5, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n39", "cat": "vintage", "name": "Cow Vintage", "addr": "3 Carlton Street, Hockley, NG1 1NL", "text": "A big vintage clothing store listed among the city's go-to second-hand fashion shops, with racks of denim, sportswear and retro jackets.", "tip": "Two floors, 1980s to early 2000s; check it's trading", "lat": 52.95363, "lon": -1.14499, "price": 0, "walk": 5, "img": "img/n39.svg", "q": "Cow Vintage, 3 Carlton Street, Hockley, NG1 1NL, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": ["m", "w"]}, {"id": "n40", "cat": "vintage", "name": "Goose Gate vintage & Hockley shops", "addr": "Goose Gate, Hockley, NG1 1FF", "text": "Goose Gate and Carlton Street are Hockley's main browsing streets: vintage clothes, skate and streetwear, plants, tattoo parlours and bars. Boots grew from the herbalist's shop John Boot opened on Goose Gate in 1849, and his son Jesse built his first big store at 16–20 Goose Gate in the 1880s. Look up for the original ironwork.", "tip": "Best late morning before the bars fill", "lat": 52.953652, "lon": -1.143536, "price": 0, "walk": 7, "img": "img/n40.svg", "q": "Goose Gate vintage & Hockley shops, Goose Gate, Hockley, NG1 1FF, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n41", "cat": "cafes", "name": "200 Degrees, Flying Horse Walk", "addr": "Flying Horse Walk, NG1 2HN", "text": "The Nottingham-born roaster that went national. This branch sits in the old coaching-inn arcade, and beans are roasted in the city.", "tip": "Buy a bag of beans to take home", "lat": 52.953065, "lon": -1.148737, "price": 1, "walk": 1, "img": "img/n41.svg", "q": "200 Degrees, Flying Horse Walk, Flying Horse Walk, NG1 2HN, Nottingham", "ta": true, "far": false, "web": "https://200degs.com", "drive": "", "who": []}, {"id": "n42", "cat": "cafes", "name": "Doughnotts", "addr": "14 Cheapside, NG1 2HU", "text": "Nottingham's own doughnut company, started here in 2015, with its city café on Cheapside beside the Council House. Big, inventive, sourdough doughnuts with vegan options.", "tip": "Closed Mondays · get there before they sell out", "lat": 52.95328, "lon": -1.14778, "price": 1, "walk": 2, "img": "img/n42.svg", "q": "Doughnotts, 14 Cheapside, NG1 2HU, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n43", "cat": "cafes", "name": "The Pudding Pantry", "addr": "Trinity Square, NG1 4AF", "text": "Over-the-top pancake stacks, brunches and cakes. Exactly what it sounds like, and very popular.", "tip": "Weekend queues from 10am", "lat": 52.95652, "lon": -1.149077, "price": 2, "walk": 6, "img": "img/n43.svg", "q": "The Pudding Pantry, Trinity Square, NG1 4AF, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n44", "cat": "cafes", "name": "Debbie Bryan tearoom", "addr": "1st floor, 4–6 St Peter's Gate, NG1 2JG", "text": "Tea, cake and light lunches among the makers' displays at Debbie Bryan's creative shop.", "tip": "Combine with a craft workshop", "lat": 52.95215, "lon": -1.1479, "price": 1, "walk": 3, "img": "img/n44.svg", "q": "Debbie Bryan tearoom, 1st floor, 4–6 St Peter's Gate, NG1 2JG, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n45", "cat": "cafes", "name": "Malt Cross", "addr": "16 St James's Street, NG1 6FG", "text": "A rare surviving 1877 Victorian music hall, with a glass barrel-vaulted roof and iron balconies, now a charity-run café-bar. Coffee by day, drinks and music at night, and caves below with a small exhibition space.", "tip": "Ask if the caves are open to wander", "lat": 52.95307, "lon": -1.152407, "price": 1, "walk": 3, "img": "img/n45.svg", "q": "Malt Cross, 16 St James's Street, NG1 6FG, Nottingham", "ta": true, "far": false, "web": "https://www.maltcross.com", "drive": "", "who": []}, {"id": "n46", "cat": "cheap", "name": "Bustler Market", "addr": "Sneinton Market Avenues, NG1 1DW", "text": "A big street-food hall with permanent traders, bars and 500+ seats in Sneinton Market. Something for everyone and very sociable.", "tip": "Busiest and best Fri–Sat evenings", "lat": 52.954286, "lon": -1.137591, "price": 1, "walk": 13, "img": "img/n46.svg", "q": "Bustler Market, Sneinton Market Avenues, NG1 1DW, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n48", "cat": "cheap", "name": "Shanghai Shanghai", "addr": "15 Goose Gate, Hockley, NG1 1FE", "text": "Proper numbing Sichuan cooking in a no-frills Hockley dining room. A local favourite for years.", "tip": "Share in a group; order the dry-fried green beans", "lat": 52.95375, "lon": -1.14312, "price": 2, "walk": 7, "img": "img/n48.svg", "q": "Shanghai Shanghai, 15 Goose Gate, Hockley, NG1 1FE, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n49", "cat": "cheap", "name": "Kayal", "addr": "8 Broad Street, Hockley, NG1 3AL", "text": "South Indian cooking from Kerala: dosas, coconut curries and seafood. A refreshing change from the standard curry house.", "tip": "The lunchtime thali is excellent value", "lat": 52.953869, "lon": -1.143772, "price": 2, "walk": 7, "img": "img/n49.svg", "q": "Kayal, 8 Broad Street, Hockley, NG1 3AL, Nottingham", "ta": true, "far": false, "web": "https://www.kayalrestaurant.com", "drive": "", "who": []}, {"id": "n50", "cat": "mid", "name": "Kushi-ya", "addr": "Enfield Chambers, 14a Low Pavement, NG1 7DL", "text": "A small, buzzy izakaya that moved in 2024 to Enfield Chambers, reached through a gated alleyway off Low Pavement. Charcoal-grilled skewers, Japanese small plates, and strong sake and natural wine lists.", "tip": "Sit at the counter to watch the grill", "lat": 52.95124, "lon": -1.14772, "price": 3, "walk": 4, "img": "img/n50.svg", "q": "Kushi-ya, Enfield Chambers, 14a Low Pavement, NG1 7DL, Nottingham", "ta": true, "far": false, "web": "https://www.kushi-ya.co.uk", "drive": "", "who": []}, {"id": "n51", "cat": "mid", "name": "Ibérico World Tapas", "addr": "The Shire Hall, High Pavement, NG1 1HN", "text": "Tapas in the vaulted, tiled basement of the old Shire Hall, candlelit and romantic. Spanish classics with detours to Asia and South America.", "tip": "The set lunch is great value", "lat": 52.95084, "lon": -1.14443, "price": 3, "walk": 7, "img": "img/n51.svg", "q": "Ibérico World Tapas, The Shire Hall, High Pavement, NG1 1HN, Nottingham", "ta": true, "far": false, "web": "https://www.ibericotapas.com", "drive": "", "who": []}, {"id": "n52", "cat": "mid", "name": "Bar Gigi", "addr": "Flying Horse Walk, NG1 2HN", "text": "A small Italian bar and kitchen in the Flying Horse Walk arcade, five years old in 2026. Aperitivo, pasta and a famously good burger.", "tip": "Casual lunch between shops", "lat": 52.953072, "lon": -1.148549, "price": 2, "walk": 1, "img": "img/n52.svg", "q": "Bar Gigi, Flying Horse Walk, NG1 2HN, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n53", "cat": "mid", "name": "Sexy Mamma Love Spaghetti", "addr": "3 Heathcoat Street, Hockley, NG1 3AF", "text": "The name's a joke but the pasta isn't. A tiny, cosy, family-run trattoria in Hockley with fresh pasta.", "tip": "No bookings: walk in and expect a short wait", "lat": 52.953822, "lon": -1.143596, "price": 2, "walk": 7, "img": "img/n53.svg", "q": "Sexy Mamma Love Spaghetti, 3 Heathcoat Street, Hockley, NG1 3AF, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n54", "cat": "mid", "name": "Shio", "addr": "Six Richmond House, Hurts Yard, NG1 6JD", "text": "A small, well-reviewed Japanese restaurant hidden in Six Richmond House in the Hurts Yard alley of independents.", "tip": "New places change fast; check menu and hours", "lat": 52.9545, "lon": -1.15254, "price": 2, "walk": 4, "img": "img/n54.svg", "q": "Shio, Six Richmond House, Hurts Yard, NG1 6JD, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n55", "cat": "mid", "name": "Café Roya", "addr": "130 Wollaton Road, Beeston, NG9 2PE", "text": "A much-loved vegetarian and vegan restaurant in Beeston with Persian-influenced cooking. Worth the tram ride.", "tip": "Small and mostly evenings; book", "lat": 52.930074, "lon": -1.218917, "price": 2, "walk": 86, "img": "img/n55.svg", "q": "Café Roya, 130 Wollaton Road, Beeston, NG9 2PE, Nottingham", "ta": true, "far": true, "web": "", "drive": "", "who": []}, {"id": "n56", "cat": "splurge", "name": "Alchemilla", "addr": "192 Derby Road, NG7 1NF", "text": "Alex Bond's Michelin-starred restaurant, built into a long-derelict Victorian coach house with a living roof. Inventive, vegetable-led tasting menus.", "tip": "Book weeks ahead · 15-min walk up Derby Road", "lat": 52.955033, "lon": -1.165557, "price": 4, "walk": 17, "img": "img/n56.svg", "q": "Alchemilla, 192 Derby Road, NG7 1NF, Nottingham", "ta": true, "far": false, "web": "https://www.alchemillarestaurant.uk", "drive": "", "who": []}, {"id": "n57", "cat": "splurge", "name": "Restaurant Sat Bains", "addr": "Lenton Lane, NG7 2SA", "text": "Nottingham's two-Michelin-star restaurant with rooms, curiously sited by the river under a flyover. One of the UK's great tasting menus; stay over and skip the drive home.", "tip": "Opens fewer days than it used to; book well ahead", "lat": 52.9353, "lon": -1.169, "price": 4, "walk": 39, "img": "img/n57.svg", "q": "Restaurant Sat Bains, Lenton Lane, NG7 2SA, Nottingham", "ta": true, "far": true, "web": "https://www.restaurantsatbains.com", "drive": "", "who": []}, {"id": "n58", "cat": "splurge", "name": "Hart's Kitchen", "addr": "Standard Hill, Park Row, NG1 6GN", "text": "A long-running, grown-up brasserie by the Castle, in Hart's Hotel. Reliable, polished modern British cooking.", "tip": "Lovely for Sunday lunch", "lat": 52.95147, "lon": -1.15662, "price": 3, "walk": 8, "img": "img/n58.svg", "q": "Hart's Kitchen, Standard Hill, Park Row, NG1 6GN, Nottingham", "ta": true, "far": false, "web": "https://www.hartsnottingham.co.uk", "drive": "", "who": []}, {"id": "n59", "cat": "pubs", "name": "Ye Olde Trip to Jerusalem", "addr": "1 Brewhouse Yard, NG1 6AD", "text": "Painted with '1189 AD', it claims to be England's oldest inn. The back rooms are caves cut straight into the sandstone under the Castle. Find the cursed model galleon in its glass case.", "tip": "Weekday afternoon for a cave room", "lat": 52.949362, "lon": -1.15267, "price": 1, "walk": 8, "img": "img/n59.svg", "q": "Ye Olde Trip to Jerusalem, 1 Brewhouse Yard, NG1 6AD, Nottingham", "ta": true, "far": false, "web": "https://www.triptojerusalem.com", "drive": "", "who": []}, {"id": "n60", "cat": "pubs", "name": "The Bell Inn", "addr": "18 Angel Row, NG1 6HL", "text": "A timber-framed pub right on the Market Square with medieval cellars and caves carved into the rock beneath. Live jazz some nights.", "tip": "Ask about cellar tours", "lat": 52.953387, "lon": -1.152056, "price": 1, "walk": 3, "img": "img/n60.svg", "q": "The Bell Inn, 18 Angel Row, NG1 6HL, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n61", "cat": "pubs", "name": "Hand & Heart", "addr": "65 Derby Road, NG1 5BA", "text": "An ordinary-looking frontage, but the back room is a cave carved into the sandstone cliff. Good real ales and food, and calmer than the Trip. It reopened under new owners after closing in 2022.", "tip": "Sit in the cave room", "lat": 52.955402, "lon": -1.160238, "price": 1, "walk": 12, "img": "img/n61.svg", "q": "Hand & Heart, 65 Derby Road, NG1 5BA, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n62", "cat": "pubs", "name": "Kean's Head", "addr": "46 St Mary's Gate, NG1 1QA", "text": "A small, friendly corner pub opposite St Mary's church in the Lace Market. Castle Rock ales and decent food.", "tip": "Stop between galleries", "lat": 52.95131, "lon": -1.144043, "price": 1, "walk": 7, "img": "img/n62.svg", "q": "Kean's Head, 46 St Mary's Gate, NG1 1QA, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n63", "cat": "pubs", "name": "The Kilpin Beer Cafe", "addr": "10 Bridlesmith Walk, NG1 2HR", "text": "Formerly The Herbert Kilpin, named after the Nottingham lace worker who founded AC Milan. A cosy little bar with well-kept cask ales and craft beer.", "tip": "Trivia to drop on your friends", "lat": 52.952, "lon": -1.1474, "price": 1, "walk": 3, "img": "img/n63.svg", "q": "The Kilpin Beer Cafe, 10 Bridlesmith Walk, NG1 2HR, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n64", "cat": "pubs", "name": "The Organ Grinder", "addr": "21 Alfreton Road, Canning Circus, NG7 3JE", "text": "Blue Monkey brewery's pub at Canning Circus. Unpretentious, excellent beer and the famous pork pie and cheese plates.", "tip": "Pair with the Borlase Warren opposite", "lat": 52.956382, "lon": -1.16292, "price": 1, "walk": 15, "img": "img/n64.svg", "q": "The Organ Grinder, 21 Alfreton Road, Canning Circus, NG7 3JE, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n65", "cat": "pubs", "name": "Sir John Borlase Warren", "addr": "1 Ilkeston Road, Canning Circus, NG7 3GD", "text": "A rambling old pub of small rooms at the top of Derby Road, with a sun-trap beer garden.", "tip": "Last stop before strolling back down", "lat": 52.955768, "lon": -1.162267, "price": 1, "walk": 14, "img": "img/n65.svg", "q": "Sir John Borlase Warren, 1 Ilkeston Road, Canning Circus, NG7 3GD, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n66", "cat": "pubs", "name": "The Lincolnshire Poacher", "addr": "161 Mansfield Road, NG1 3FR", "text": "A pilgrimage pub for beer people, a 15-minute walk up Mansfield Road. Long tap list, whisky shelf, no nonsense.", "tip": "Mansfield Road has more good pubs for a crawl", "lat": 52.962165, "lon": -1.151416, "price": 1, "walk": 16, "img": "img/n66.svg", "q": "The Lincolnshire Poacher, 161 Mansfield Road, NG1 3FR, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n67", "cat": "pubs", "name": "Fox & Grapes", "addr": "21 Southwell Road, Sneinton, NG1 1DL", "text": "A Castle Rock pub on the edge of Sneinton Market, handy for galleries, studios and Bustler.", "tip": "Pair with Surface Gallery", "lat": 52.95367, "lon": -1.13771, "price": 1, "walk": 13, "img": "img/n67.svg", "q": "Fox & Grapes, 21 Southwell Road, Sneinton, NG1 1DL, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n68", "cat": "pubs", "name": "The Vat & Fiddle", "addr": "12–14 Queen's Bridge Road, NG2 1NB", "text": "Castle Rock brewery's own tap, next to the brewery and a few minutes from the station. Fresh ales and a proper local atmosphere.", "tip": "Last pint before the train", "lat": 52.9457, "lon": -1.14833, "price": 1, "walk": 14, "img": "img/n68.svg", "q": "The Vat & Fiddle, 12–14 Queen's Bridge Road, NG2 1NB, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n69", "cat": "pubs", "name": "The Angel Microbrewery", "addr": "7 Stoney Street, Lace Market, NG1 1LG", "text": "A historic Lace Market pub with its own microbrewery, gigs upstairs and a slightly chaotic, friendly vibe.", "tip": "Check the gig listings", "lat": 52.95339, "lon": -1.143392, "price": 1, "walk": 7, "img": "img/n69.svg", "q": "The Angel Microbrewery, 7 Stoney Street, Lace Market, NG1 1LG, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n70", "cat": "bars", "name": "The Hockley Arts Club", "addr": "20A Carlton Street, Hockley, NG1 1NN", "text": "A grand cocktail bar in a Grade II-listed building, dressed with art and music memorabilia. One of the city's showier nights out.", "tip": "Wed–Sun · lively late at weekends", "lat": 52.95331, "lon": -1.14433, "price": 3, "walk": 6, "img": "img/n70.svg", "q": "The Hockley Arts Club, 20A Carlton Street, Hockley, NG1 1NN, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n71", "cat": "bars", "name": "Junkyard", "addr": "12 Bridlesmith Walk, NG1 2HR", "text": "A small, dark, serious craft beer bar with a rotating tap list and good bar food.", "tip": "Ask the staff for a recommendation", "lat": 52.952503, "lon": -1.146155, "price": 2, "walk": 4, "img": "img/n71.svg", "q": "Junkyard, 12 Bridlesmith Walk, NG1 2HR, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n72", "cat": "bars", "name": "The Canal House", "addr": "48–52 Canal Street, NG1 7EH", "text": "An arm of the Nottingham Canal runs right through the middle of the bar, with a footbridge over it and a canalside terrace.", "tip": "Sit by the water inside", "lat": 52.94827, "lon": -1.14856, "price": 2, "walk": 9, "img": "img/n72.svg", "q": "The Canal House, 48–52 Canal Street, NG1 7EH, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n73", "cat": "bars", "name": "Broadway Cinema bar", "addr": "14–18 Broad Street, NG1 3AL", "text": "The independent cinema's café-bar, open to everyone. Full of film people and Hockley regulars.", "tip": "Pair with a film", "lat": 52.954306, "lon": -1.143663, "price": 1, "walk": 7, "img": "img/n73.svg", "q": "Broadway Cinema bar, 14–18 Broad Street, NG1 3AL, Nottingham", "ta": true, "far": false, "web": "https://www.broadway.org.uk", "drive": "", "who": []}, {"id": "n74", "cat": "bars", "name": "The Bodega", "addr": "23 Pelham Street, NG1 2ED", "text": "A pub downstairs and a small gig venue upstairs, where plenty of bands played early in their careers. A Hockley staple for a pint and a gig.", "tip": "Check the gig calendar", "lat": 52.953751, "lon": -1.145948, "price": 1, "walk": 4, "img": "img/n74.svg", "q": "The Bodega, 23 Pelham Street, NG1 2ED, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n75", "cat": "gear", "name": "Wex Photo Video", "addr": "103–107 Carrington Street, NG1 7FE", "text": "A big camera shop near the station with a proper used counter: second-hand lenses, bodies, flashes and accessories, all with a 12-month warranty. Stock changes daily and isn't all online, so it's worth a browse in person. They'll also buy or part-exchange your old kit.", "tip": "Used stock is first come, first served", "lat": 52.947804, "lon": -1.147325, "price": 0, "walk": 10, "img": "img/n75.svg", "q": "Wex Photo Video, 103–107 Carrington Street, NG1 7FE, Nottingham", "ta": true, "far": false, "web": "https://www.wexphotovideo.com/about-us/store-finder/nottingham/", "drive": "", "who": []}, {"id": "n77", "cat": "gear", "name": "Drum & Guitar", "addr": "Cranbrook House, Cranbrook Street, NG1 1ES", "text": "Calls itself the largest independent music store in the East Midlands. Especially strong on drums, cymbals and percussion, with guitars and amps too, and staff who know their stuff.", "tip": "Ask about part-exchange and any used stock", "lat": 52.954089, "lon": -1.141337, "price": 0, "walk": 9, "img": "img/n77.svg", "q": "Drum & Guitar, Cranbrook House, Cranbrook Street, NG1 1ES, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n78", "cat": "gear", "name": "Nottingham City Guitars", "addr": "Lace Market, NG1", "text": "A luthier's workshop building hand-made electric guitars, with some finished shop stock for sale. Guitars start from around £1,500. A treat for a serious player.", "tip": "Open by appointment only; contact them first", "lat": 52.9523, "lon": -1.144, "price": 0, "walk": 7, "img": "img/n78.svg", "q": "Nottingham City Guitars, Lace Market, NG1, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n79", "cat": "gear", "name": "CeX, Victoria Centre", "addr": "Unit 310, Upper Mall, Victoria Centre, NG1 3QN", "text": "The buy-sell-exchange chain for second-hand phones, laptops, tablets, cameras, consoles and games, everything graded with a warranty. Handy for a cheap spare phone or a retro console.", "tip": "A second branch is on Exchange Walk", "lat": 52.9563, "lon": -1.1477, "price": 0, "walk": 6, "img": "img/n79.svg", "q": "CeX, Victoria Centre, Unit 310, Upper Mall, Victoria Centre, NG1 3QN, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n80", "cat": "gear", "name": "CeX, Exchange Walk", "addr": "2 Exchange Walk, NG1 2NX", "text": "The smaller central CeX, just off the Old Market Square, for second-hand tech, games and phones.", "tip": "Compare stock with the Victoria Centre branch", "lat": 52.952971, "lon": -1.148972, "price": 0, "walk": 1, "img": "img/n80.svg", "q": "CeX, Exchange Walk, 2 Exchange Walk, NG1 2NX, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n81", "cat": "food", "name": "The Cheese Shop", "addr": "4 Flying Horse Walk, NG1 2HN", "text": "Run by brothers Rob and Webb Freckingham for more than 15 years: a counter of British and continental cheeses, charcuterie, chutneys and crackers, plus the only café in Flying Horse Walk. A past World Cheese Awards placer.", "tip": "Ask for Colston Bassett or Cropwell Bishop Stilton, both made in Notts", "lat": 52.95281, "lon": -1.148486, "price": 0, "walk": 2, "img": "img/n81.svg", "q": "The Cheese Shop, 4 Flying Horse Walk, NG1 2HN, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n82", "cat": "food", "name": "Oriental Mart", "addr": "1A Goldsmith Street, NG1 5ED", "text": "Nottingham's best-known East Asian supermarket, with more than 3,000 Chinese, Japanese, Korean, Thai and Vietnamese products: fresh, frozen and dried. Its Umai street-food café serves bao, ramen and Hong Kong snacks.", "tip": "Good for snacks you won't find anywhere else", "lat": 52.955294, "lon": -1.152352, "price": 0, "walk": 5, "img": "img/n82.svg", "q": "Oriental Mart, 1A Goldsmith Street, NG1 5ED, Nottingham", "ta": true, "far": false, "web": "https://www.orientalmart.co.uk", "drive": "", "who": []}, {"id": "n83", "cat": "food", "name": "Asiana Hypermarket", "addr": "108 Woodborough Road, NG3 1AR", "text": "A huge Oriental supermarket on the edge of the centre, stocking foods from China, Hong Kong, Korea, Thailand, Japan, Vietnam and the Philippines, with big fresh and frozen sections.", "tip": "Easiest by car; it's uphill from Victoria Centre", "lat": 52.962281, "lon": -1.14675, "price": 0, "walk": 17, "img": "img/n83.svg", "q": "Asiana Hypermarket, 108 Woodborough Road, NG3 1AR, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n84", "cat": "food", "name": "Radford Road world food trail", "addr": "Radford Road, Hyson Green, NG7", "text": "Half a mile of international grocers and bakeries where a dozen languages are spoken: South Asian and Middle Eastern spices at Medina Continental (79–83 Radford Road), exotic fruit and veg at Green Oranges, Polish bakes at Olawa Bakery and Eastern European goods at the Tani Shop. Wiloks nearby does African and Caribbean foods.", "tip": "Tram to Hyson Green Market; pair with New Art Exchange", "lat": 52.964717, "lon": -1.170356, "price": 0, "walk": 31, "img": "img/n84.svg", "q": "Radford Road world food trail, Radford Road, Hyson Green, NG7, Nottingham", "ta": false, "far": true, "web": "", "drive": "", "who": []}, {"id": "n85", "cat": "fun", "name": "Cave Escape", "addr": "63 Mansfield Road, NG1 3FN", "text": "Escape rooms built into a real sandstone cave system under Mansfield Road, which could only be in Nottingham. Three rooms for up to 18 players at once.", "tip": "Book ahead, especially at weekends", "lat": 52.959891, "lon": -1.15004, "price": 0, "walk": 12, "img": "img/n85.svg", "q": "Cave Escape, 63 Mansfield Road, NG1 3FN, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n86", "cat": "fun", "name": "Escapologic", "addr": "21–23 Castle Gate, NG1 7AQ", "text": "The city's biggest escape-room venue, with 11 themed rooms across two buildings including 18+ horror games in the autumn.", "tip": "20% off a second room booked on the day · check hours", "lat": 52.950988, "lon": -1.149794, "price": 0, "walk": 4, "img": "img/n86.svg", "q": "Escapologic, 21–23 Castle Gate, NG1 7AQ, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n87", "cat": "fun", "name": "Break Escape", "addr": "9a Market Street & 107 Upper Parliament Street, NG1", "text": "A family-friendly escape-room company with two city-centre sites and a Robin Hood-themed room, plus Christmas rooms in December.", "tip": "Cheaper tickets for children", "lat": 52.954093, "lon": -1.151414, "price": 0, "walk": 2, "img": "img/n87.svg", "q": "Break Escape, 9a Market Street & 107 Upper Parliament Street, NG1, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n88", "cat": "fun", "name": "The Original Nottingham Ghost Walk", "addr": "Starts at Ye Olde Trip to Jerusalem, NG1 6AD", "text": "A costumed storyteller leads you round the Castle Quarter after dark, telling the city's ghost stories over about half a mile. Runs on Saturday evenings; the 2026 season ends on 7 December.", "tip": "Saturdays 7pm · £9 · about 1½–2 hours", "lat": 52.949362, "lon": -1.15267, "price": 0, "walk": 8, "img": "img/n88.svg", "q": "The Original Nottingham Ghost Walk, Starts at Ye Olde Trip to Jerusalem, NG1 6AD, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n89", "cat": "fun", "name": "Ludorati Café", "addr": "72 Maid Marian Way, NG1 6BJ", "text": "A board-game café with over 750 games, from old favourites to new ones, plus coffee, food and staff who'll teach you the rules. Great on a rainy afternoon.", "tip": "Book a table at weekends", "lat": 52.952, "lon": -1.153, "price": 0, "walk": 4, "img": "img/n89.svg", "q": "Ludorati Café, 72 Maid Marian Way, NG1 6BJ, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n90", "cat": "fun", "name": "The Dice Cup", "addr": "68–70 Mansfield Road, NG1 3GY", "text": "Nottingham's first board-game café and a proper games shop: dice, board games, tabletop miniatures and comics, with vegan-friendly food.", "tip": "Browse the shop even if you're not staying to play", "lat": 52.959179, "lon": -1.14918, "price": 0, "walk": 11, "img": "img/n90.svg", "q": "The Dice Cup, 68–70 Mansfield Road, NG1 3GY, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n91", "cat": "music", "name": "Rock City", "addr": "8 Talbot Street, NG1 5GG", "text": "A legendary independent rock venue since 1980, holding about 2,000 people. Just about every big guitar band of the last 40 years has played here, and its club nights are a Nottingham rite of passage.", "tip": "Check listings and book early for touring bands", "lat": 52.956062, "lon": -1.154025, "price": 0, "walk": 7, "img": "img/n91.svg", "q": "Rock City, 8 Talbot Street, NG1 5GG, Nottingham", "ta": true, "far": false, "web": "https://www.rock-city.co.uk", "drive": "", "who": []}, {"id": "n92", "cat": "music", "name": "Rescue Rooms", "addr": "Masonic Place, off Goldsmith Street, NG1 5JT", "text": "Rock City's 480-capacity little sibling next door, where you catch bands on the way up. It has a bar and kitchen, so it works for a drink even without a gig.", "tip": "Tickets often around £15–25", "lat": 52.95608, "lon": -1.153468, "price": 0, "walk": 6, "img": "img/n92.svg", "q": "Rescue Rooms, Masonic Place, off Goldsmith Street, NG1 5JT, Nottingham", "ta": true, "far": false, "web": "https://www.rescuerooms.com", "drive": "", "who": []}, {"id": "n93", "cat": "music", "name": "Metronome & the Glee Club", "addr": "Huntingdon Street, NG1 1AP", "text": "Nottingham Trent University's music and arts venue, now home to the Glee Club's comedy nights and Just the Tonic, plus gigs and club nights.", "tip": "Comedy weekends sell out; book ahead", "lat": 52.955916, "lon": -1.142529, "price": 0, "walk": 9, "img": "img/n93.svg", "q": "Metronome & the Glee Club, Huntingdon Street, NG1 1AP, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n94", "cat": "music", "name": "Nottingham Playhouse", "addr": "Wellington Circus, NG1 5AF", "text": "The city's producing theatre, with drama, its famous panto and touring work. Outside stands Anish Kapoor's Sky Mirror, a huge polished steel dish reflecting the sky, which is worth a look even if you're not seeing a show.", "tip": "The Sky Mirror is free to see any time", "lat": 52.953968, "lon": -1.156158, "price": 0, "walk": 7, "img": "img/n94.svg", "q": "Nottingham Playhouse, Wellington Circus, NG1 5AF, Nottingham", "ta": true, "far": false, "web": "https://www.nottinghamplayhouse.co.uk", "drive": "", "who": []}, {"id": "n95", "cat": "pubs", "name": "Ye Olde Salutation Inn", "addr": "Hounds Gate, NG1 7AA", "text": "A 13th-century-founded pub with caves beneath it, and a long-standing rock and live-music haunt. A third contender in the 'oldest pub in Nottingham' argument.", "tip": "Ask about seeing the caves", "lat": 52.951109, "lon": -1.151672, "price": 1, "walk": 4, "img": "img/n95.svg", "q": "Ye Olde Salutation Inn, Hounds Gate, NG1 7AA, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n96", "cat": "parks", "name": "Victoria Embankment", "addr": "Victoria Embankment, NG2", "text": "A broad tree-lined promenade along the River Trent, with memorial gardens, rowing clubs and views of Trent Bridge, the cricket ground and the City Ground. Flat and easy, and best on a sunny afternoon.", "tip": "Tram to Meadows Embankment", "lat": 52.9342, "lon": -1.138, "price": 0, "walk": 37, "img": "img/n96.svg", "q": "Victoria Embankment, Victoria Embankment, NG2, Nottingham", "ta": true, "far": true, "web": "", "drive": "", "who": []}, {"id": "n97", "cat": "parks", "name": "Nottingham Canal towpath", "addr": "Castle Wharf, Canal Street, NG1 7EH", "text": "Join the canal by the Canal House and walk west past old warehouses, narrowboats and Castle Marina. It's flat all the way, and you can carry on for an hour or more towards Beeston.", "tip": "Start or finish with a drink at the Canal House", "lat": 52.948137, "lon": -1.15026, "price": 0, "walk": 9, "img": "img/n97.svg", "q": "Nottingham Canal towpath, Castle Wharf, Canal Street, NG1 7EH, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n98", "cat": "parks", "name": "Highfields Park", "addr": "University Boulevard, NG7 2PS", "text": "A lakeside Victorian park beside the University of Nottingham, with a boating lake, a waterfall, a café and Lakeside Arts. Pair it with a walk up through the campus to the Trent Building.", "tip": "Tram to University of Nottingham", "lat": 52.936076, "lon": -1.193538, "price": 0, "walk": 57, "img": "img/n98.svg", "q": "Highfields Park, University Boulevard, NG7 2PS, Nottingham", "ta": true, "far": true, "web": "", "drive": "", "who": []}, {"id": "n99", "cat": "parks", "name": "The Forest Recreation Ground", "addr": "Mansfield Road, NG7", "text": "A huge open green on the hill north of the centre, home to Goose Fair every October and a tram Park & Ride. Big skies and views back over the city.", "tip": "The Forest tram stop is right there", "lat": 52.965334, "lon": -1.16093, "price": 0, "walk": 25, "img": "img/n99.svg", "q": "The Forest Recreation Ground, Mansfield Road, NG7, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n100", "cat": "parks", "name": "Colwick Country Park", "addr": "Mile End Road, Colwick, NG4 2DW", "text": "Lakes, woods and riverside paths on the east side of the city, with a marina and plenty of birdlife. Easy circular walks.", "tip": "About 10 minutes' drive; paid parking", "lat": 52.948382, "lon": -1.095981, "price": 0, "walk": 59, "img": "img/n100.svg", "q": "Colwick Country Park, Mile End Road, Colwick, NG4 2DW, Nottingham", "ta": true, "far": true, "web": "", "drive": "", "who": []}, {"id": "n101", "cat": "parks", "name": "Attenborough Nature Reserve", "addr": "Barton Lane, Attenborough, NG9 6DY", "text": "Flooded gravel pits turned into a wildlife haven beside the Trent, opened by Sir David Attenborough. A floating nature centre and café, kingfishers, herons and easy level paths.", "tip": "Train to Attenborough station, or 20 minutes by car", "lat": 52.899645, "lon": -1.235677, "price": 0, "walk": 135, "img": "img/n101.svg", "q": "Attenborough Nature Reserve, Barton Lane, Attenborough, NG9 6DY, Nottingham", "ta": true, "far": true, "web": "", "drive": "", "who": []}, {"id": "n102", "cat": "trips", "name": "Sherwood Forest & the Major Oak", "addr": "Edwinstowe, NG21", "text": "The heart of the old royal forest, with ancient oaks and woodland trails around the Major Oak, a giant tree held up by props and thought to be 800–1,000 years old. The visitor centre is in Edwinstowe, where legend says Robin Hood married Marian.", "tip": "Go early on weekends; Robin Hood Festival in August", "lat": 53.2048, "lon": -1.0724, "price": 0, "walk": 462, "img": "img/n102.svg", "q": "Sherwood Forest & the Major Oak, Edwinstowe, NG21, Nottingham", "ta": true, "far": true, "web": "", "drive": "40 min", "who": []}, {"id": "n103", "cat": "trips", "name": "Newstead Abbey", "addr": "Ravenshead, NG15 8NA", "text": "Lord Byron's ancestral home: the soaring west front of a medieval priory ruin attached to a country house, set in lakes, gardens and parkland with peacocks.", "tip": "Gardens daily · house weekends & school holidays 11–4", "lat": 53.078407, "lon": -1.192436, "price": 0, "walk": 231, "img": "img/n103.svg", "q": "Newstead Abbey, Ravenshead, NG15 8NA, Nottingham", "ta": true, "far": true, "web": "https://newsteadabbey.org.uk", "drive": "25 min", "who": []}, {"id": "n104", "cat": "trips", "name": "Southwell", "addr": "Southwell, NG25", "text": "A small Georgian minster town. The Norman Minster's chapter house has the famous 'Leaves of Southwell' stone carvings, and the National Trust Workhouse shows Victorian poor-relief. There are good independent shops and tearooms, and the Bramley apple started here.", "tip": "Pair the Minster and Workhouse with lunch in town", "lat": 53.076847, "lon": -0.954138, "price": 0, "walk": 308, "img": "img/n104.svg", "q": "Southwell, Southwell, NG25, Nottingham", "ta": true, "far": true, "web": "", "drive": "35 min", "who": []}, {"id": "n105", "cat": "trips", "name": "Creswell Crags", "addr": "Crags Road, Welbeck, S80 3LH", "text": "A limestone gorge of caves holding the UK's only known Ice Age cave art, plus hundreds of 'witches' marks' scratched to ward off evil. Guided cave tours, a lakeside walk and a visitor centre.", "tip": "Cave tours are guided; no under-5s on tours", "lat": 53.262042, "lon": -1.199179, "price": 0, "walk": 560, "img": "img/n105.svg", "q": "Creswell Crags, Crags Road, Welbeck, S80 3LH, Nottingham", "ta": true, "far": true, "web": "", "drive": "45 min", "who": []}, {"id": "n106", "cat": "trips", "name": "Clumber Park", "addr": "Worksop, S80 3BX", "text": "National Trust parkland with a big serpentine lake, a Gothic chapel, one of the longest double avenues of lime trees in Europe and a beautiful walled kitchen garden. Bikes to hire.", "tip": "Great for a long walk or a bike ride", "lat": 53.267873, "lon": -1.059039, "price": 0, "walk": 577, "img": "img/n106.svg", "q": "Clumber Park, Worksop, S80 3BX, Nottingham", "ta": true, "far": true, "web": "", "drive": "40 min", "who": []}, {"id": "n107", "cat": "trips", "name": "Hardwick Hall", "addr": "Doe Lea, Chesterfield, S44 5QJ", "text": "Bess of Hardwick's dazzling Elizabethan house, famous as 'more glass than wall', with huge tapestries and her initials on the rooftop. The ruined Old Hall stands next door.", "tip": "Just off M1 junction 29", "lat": 53.167998, "lon": -1.308801, "price": 0, "walk": 425, "img": "img/n107.svg", "q": "Hardwick Hall, Doe Lea, Chesterfield, S44 5QJ, Nottingham", "ta": true, "far": true, "web": "", "drive": "35 min", "who": []}, {"id": "n108", "cat": "trips", "name": "Ruddington", "addr": "Ruddington, NG11", "text": "A village with the Framework Knitters Museum (working Victorian knitting frames in original workshops), the Great Central Railway heritage steam and diesel line, and Debbie Bryan's second shop.", "tip": "Check the railway's running days", "lat": 52.891121, "lon": -1.151772, "price": 0, "walk": 112, "img": "img/n108.svg", "q": "Ruddington, Ruddington, NG11, Nottingham", "ta": true, "far": true, "web": "", "drive": "15 min", "who": []}, {"id": "n109", "cat": "trips", "name": "Colston Bassett Dairy", "addr": "Harby Lane, Colston Bassett, NG12", "text": "One of only a handful of dairies allowed to make Stilton, still making it by hand. Its small shop sells Stilton and Shropshire Blue straight from the source, in Vale of Belvoir countryside.", "tip": "Shop hours are short: weekdays & Saturday mornings", "lat": 52.891597, "lon": -0.956947, "price": 0, "walk": 238, "img": "img/n109.svg", "q": "Colston Bassett Dairy, Harby Lane, Colston Bassett, NG12, Nottingham", "ta": true, "far": true, "web": "", "drive": "25 min", "who": []}, {"id": "n110", "cat": "trips", "name": "Belvoir Castle", "addr": "Grantham, NG32 1PE", "text": "The Duke of Rutland's romantic hilltop castle overlooking the Vale of Belvoir, with lavish state rooms and landscaped gardens. Pair it with the Colston Bassett dairy shop on the way.", "tip": "Opening is seasonal; check dates before you go", "lat": 52.894692, "lon": -0.782689, "price": 0, "walk": 414, "img": "img/n110.svg", "q": "Belvoir Castle, Grantham, NG32 1PE, Nottingham", "ta": true, "far": true, "web": "", "drive": "40 min", "who": []}, {"id": "n111", "cat": "galleries", "name": "George Thornton Art", "addr": "12A Flying Horse Walk, NG1 2HN", "text": "An independent contemporary gallery in the Flying Horse Walk arcade, championing original, thought-provoking paintings and sculpture by living artists. Offers the Own Art interest-free scheme.", "tip": "Easy to combine with The Cheese Shop next door", "lat": 52.952789, "lon": -1.148546, "price": 0, "walk": 2, "img": "img/n111.svg", "q": "George Thornton Art, 12A Flying Horse Walk, NG1 2HN, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n112", "cat": "galleries", "name": "Lauren Paige Art Gallery & Writing Bureau", "addr": "211 Mansfield Road, NG1 3FS", "text": "A one-artist gallery in a Victorian terrace at the Huntingdon Street junction, selling Lauren Paige's original paintings and limited-edition prints, with a writing bureau alongside.", "tip": "Free 2-hour parking on North Sherwood Street behind", "lat": 52.963289, "lon": -1.151988, "price": 0, "walk": 18, "img": "img/n112.svg", "q": "Lauren Paige Art Gallery & Writing Bureau, 211 Mansfield Road, NG1 3FS, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n113", "cat": "galleries", "name": "PSpowage Art Gallery", "addr": "185 Mansfield Road, NG1 3FS", "text": "Artist Pete Spowage's gallery and studio, showing his own work and local artists. It moved here from Byard Lane in 2020 and was then open by appointment.", "tip": "Check first: by appointment and may have moved", "lat": 52.962751, "lon": -1.15166, "price": 0, "walk": 17, "img": "img/n113.svg", "q": "PSpowage Art Gallery, 185 Mansfield Road, NG1 3FS, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n114", "cat": "galleries", "name": "Castle Fine Art", "addr": "8–10 Exchange Arcade, NG1 2DD", "text": "A large commercial gallery inside the Council House's Exchange Arcade, part of a national chain selling original works and limited editions by well-known contemporary and celebrity artists. Good for browsing big names.", "tip": "Chain gallery; staff are happy for you to browse", "lat": 52.953299, "lon": -1.148418, "price": 0, "walk": 1, "img": "img/n114.svg", "q": "Castle Fine Art, 8–10 Exchange Arcade, NG1 2DD, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n115", "cat": "galleries", "name": "Aura Fine Art", "addr": "23 Bridlesmith Gate, NG1 2GR", "text": "A commercial gallery on Bridlesmith Gate selling originals and limited editions for homes and offices, part of a small chain with branches in Hertfordshire and Guildford. Offers home consultations and flexible payment.", "tip": "Chain gallery · around 9:30–17:30", "lat": 52.95234, "lon": -1.14707, "price": 0, "walk": 3, "img": "img/n115.svg", "q": "Aura Fine Art, 23 Bridlesmith Gate, NG1 2GR, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n116", "cat": "galleries", "name": "The Harley Gallery, Welbeck", "addr": "Welbeck, Worksop, S80 3LW", "text": "A major contemporary art and craft gallery on the Welbeck estate, with the Portland Collection of treasures from the Dukes of Portland. The Harley Open exhibition runs until 3 January 2027. Pair it with Creswell Crags, ten minutes away.", "tip": "Free entry to the gallery; café and estate shops", "lat": 53.262015, "lon": -1.178983, "price": 0, "walk": 559, "img": "img/n116.svg", "q": "The Harley Gallery, Welbeck, Welbeck, Worksop, S80 3LW, Nottingham", "ta": true, "far": true, "web": "", "drive": "45 min", "who": []}, {"id": "n117", "cat": "fashion", "name": "Gigi Bottega", "addr": "15 Flying Horse Walk, NG1 2HN", "text": "An independent luxury boutique run by mother and daughter Debra and Gabriella Trivigno, with high-end and contemporary designer labels for men and women. It has a cult following.", "tip": "Treat yourself, or just browse", "lat": 52.95308, "lon": -1.148549, "price": 0, "walk": 1, "img": "img/n117.svg", "q": "Gigi Bottega, 15 Flying Horse Walk, NG1 2HN, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": ["m", "w"]}, {"id": "n118", "cat": "fashion", "name": "Tutu Urban Boutique", "addr": "Exchange Arcade, NG1 2DD", "text": "A multi-brand independent womenswear boutique, trading in Nottingham since 1989 and now in the Council House's Exchange Arcade.", "tip": "Tue–Sat 10:00–17:00", "lat": 52.9534, "lon": -1.148762, "price": 0, "walk": 1, "img": "img/n118.svg", "q": "Tutu Urban Boutique, Exchange Arcade, NG1 2DD, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": ["w"]}, {"id": "n119", "cat": "fashion", "name": "Flannels", "addr": "11–13 Lister Gate, NG1 7DE", "text": "Frasers Group's luxury multi-brand store, the kind you only find in big cities: Stone Island, Moncler, Gucci, Off-White and more for men, women and children.", "tip": "Opened 2023 in the old River Island building", "lat": 52.951152, "lon": -1.148471, "price": 0, "walk": 4, "img": "img/n119.svg", "q": "Flannels, 11–13 Lister Gate, NG1 7DE, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": ["m", "w", "k"]}, {"id": "n120", "cat": "fashion", "name": "John Lewis", "addr": "Victoria Centre, Milton Street, NG1 3QA", "text": "One of the big John Lewis department stores, which have closed in several smaller cities. Fashion for everyone including children, plus home, beauty and tech.", "tip": "Good café upstairs", "lat": 52.956066, "lon": -1.147674, "price": 0, "walk": 6, "img": "img/n120.svg", "q": "John Lewis, Victoria Centre, Milton Street, NG1 3QA, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": ["m", "w", "k"]}, {"id": "n121", "cat": "fashion", "name": "Urban Outfitters", "addr": "Victoria Centre, Milton Street, NG1 3QL", "text": "The big-city lifestyle chain: streetwear, its own vintage line, homewares, vinyl and gifts.", "tip": "Check the Urban Renewal vintage rail", "lat": 52.95536, "lon": -1.147363, "price": 0, "walk": 5, "img": "img/n121.svg", "q": "Urban Outfitters, Victoria Centre, Milton Street, NG1 3QL, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": ["m", "w"]}, {"id": "n122", "cat": "fashion", "name": "Lucy & Yak", "addr": "11 The Poultry, moving to 29 Bridlesmith Gate, NG1", "text": "The bright, sustainably made dungarees brand, mostly womenswear with lots of unisex pieces. It's moving in late 2026 to a bigger Bridlesmith Gate shop with its Re:Yak repair and pre-loved range.", "tip": "Check which address is open when you visit", "lat": 52.953082, "lon": -1.147583, "price": 0, "walk": 2, "img": "img/n122.svg", "q": "Lucy & Yak, 11 The Poultry, moving to 29 Bridlesmith Gate, NG1, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": ["w", "m"]}, {"id": "n123", "cat": "fashion", "name": "Metro Fashion", "addr": "Middle Pavement, NG1", "text": "A discount designer shop selling new, discontinued and pre-loved designer clothing for men, women and children at a fraction of retail price.", "tip": "Stock changes constantly; check it's still trading", "lat": 52.9515, "lon": -1.14632, "price": 0, "walk": 5, "img": "img/n123.svg", "q": "Metro Fashion, Middle Pavement, NG1, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": ["m", "w", "k"]}, {"id": "n124", "cat": "vintage", "name": "Glass Onion", "addr": "Bridlesmith Gate, NG1 2GQ", "text": "A big vintage clothing emporium from Yorkshire that opened in Nottingham in 2025 after success in Leeds and Sheffield: rails of graded vintage for men and women.", "tip": "A good first stop on a Bridlesmith Gate vintage crawl", "lat": 52.951678, "lon": -1.147133, "price": 0, "walk": 4, "img": "img/n124.svg", "q": "Glass Onion, Bridlesmith Gate, NG1 2GQ, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": ["m", "w"]}, {"id": "n125", "cat": "vintage", "name": "101 Vintage", "addr": "15 Bridlesmith Gate, NG1 2GR", "text": "A unisex vintage store focused on American 1990s and Y2K fashion, hand-picked and restocked daily, with around 800 items.", "tip": "Check it's trading; it was on the street as of 2021", "lat": 52.95245, "lon": -1.1472, "price": 0, "walk": 3, "img": "img/n125.svg", "q": "101 Vintage, 15 Bridlesmith Gate, NG1 2GR, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": ["m", "w"]}, {"id": "n126", "cat": "vintage", "name": "White Rose", "addr": "26a Long Row, NG1 2DR", "text": "A Nottingham-grown recycled fashion chain with around eight local shops, selling pre-loved designer and branded clothing at bargain prices.", "tip": "Another branch is in the Victoria Centre", "lat": 52.953752, "lon": -1.149683, "price": 0, "walk": 1, "img": "img/n126.svg", "q": "White Rose, 26a Long Row, NG1 2DR, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": ["m", "w"]}, {"id": "n127", "cat": "charity", "name": "Oxfam Books & Music", "addr": "19 Market Street, NG1 6HX", "text": "Oxfam's specialist shop for second-hand books, vinyl, CDs, DVDs and sheet music, sorted by volunteers who know their stuff. The best charity shop in the centre for records and music.", "tip": "Another Oxfam Books & Music is in West Bridgford", "lat": 52.954423, "lon": -1.151512, "price": 0, "walk": 3, "img": "img/n127.svg", "q": "Oxfam Books & Music, 19 Market Street, NG1 6HX, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n128", "cat": "charity", "name": "British Heart Foundation, Clumber Street", "addr": "12–14 Clumber Street, NG1 3GA", "text": "A big central BHF shop with a vintage section, plus clothes for men, women and children, books, toys and homewares.", "tip": "Open Sundays 11:00–17:00", "lat": 52.954094, "lon": -1.147371, "price": 0, "walk": 3, "img": "img/n128.svg", "q": "British Heart Foundation, Clumber Street, 12–14 Clumber Street, NG1 3GA, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": ["m", "w", "k"]}, {"id": "n129", "cat": "charity", "name": "BHF Furniture & Electrical, Bulwell", "addr": "Main Street, Bulwell, NG6", "text": "The British Heart Foundation's furniture and electrical store: second-hand sofas, tables, wardrobes and tested home appliances and electricals at charity prices, with delivery available.", "tip": "Drive or tram to Bulwell; weekday and Saturday hours", "lat": 53.00193, "lon": -1.196076, "price": 0, "walk": 101, "img": "img/n129.svg", "q": "BHF Furniture & Electrical, Bulwell, Main Street, Bulwell, NG6, Nottingham", "ta": false, "far": true, "web": "", "drive": "20 min", "who": []}, {"id": "n130", "cat": "charity", "name": "Headway Charity Shop, Mapperley", "addr": "23A Plains Road, Mapperley, NG3", "text": "A small brain-injury charity shop with a well-known vinyl section, where volunteers sort, grade and clean the records. A favourite of local crate-diggers.", "tip": "Worth a detour for record collectors", "lat": 52.984582, "lon": -1.121469, "price": 0, "walk": 64, "img": "img/n130.svg", "q": "Headway Charity Shop, Mapperley, 23A Plains Road, Mapperley, NG3, Nottingham", "ta": false, "far": true, "web": "", "drive": "15 min", "who": []}, {"id": "n131", "cat": "trips", "name": "Newark International Antiques & Collectors Fair", "addr": "Newark Showground, Lincoln Road, NG24 2NY", "text": "One of Europe's biggest antiques fairs: thousands of stalls across the Newark showground several times a year. There's also a smaller one-day 'Runway Monday' fair. The town of Newark has its own antiques centres and a castle too.", "tip": "2026: Runway Monday 23 Nov; next main fair 10–11 Dec (check)", "lat": 53.098808, "lon": -0.767005, "price": 0, "walk": 492, "img": "img/n131.svg", "q": "Newark International Antiques & Collectors Fair, Newark Showground, Lincoln Road, NG24 2NY, Nottingham", "ta": true, "far": true, "web": "", "drive": "35 min", "who": []}, {"id": "n132", "cat": "gear", "name": "London Camera Exchange", "addr": "7 Pelham Street, NG1 2EH", "text": "A camera dealer with a constantly changing used counter: film and digital bodies and lenses, often serviced, plus part-exchange. A good second stop after Wex.", "tip": "Browse the used stock on lcegroup.co.uk and reserve before you travel", "lat": 52.953779, "lon": -1.147044, "price": 0, "walk": 3, "img": "img/n132.svg", "q": "London Camera Exchange, 7 Pelham Street, NG1 2EH, Nottingham", "ta": true, "far": false, "web": "https://www.lcegroup.co.uk", "drive": "", "who": []}, {"id": "n133", "cat": "gear", "name": "Make It Easy Lab", "addr": "18 Queen's Bridge Road, NG2 1NB", "text": "A film-photography lab and darkroom offering developing, darkroom hire and courses from beginner film to wet-plate collodion. The hub of Nottingham's analogue scene.", "tip": "Workshop-based; check sessions and drop-off times first", "lat": 52.9455, "lon": -1.1481, "price": 0, "walk": 14, "img": "img/n133.svg", "q": "Make It Easy Lab, 18 Queen's Bridge Road, NG2 1NB, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n134", "cat": "charity", "name": "Sue Ryder Superstore, Clifton", "addr": "Clifton Triangle, Green Lane, NG11 9LN", "text": "A retail-park charity superstore full of donated furniture, electricals, books and clothes, plus new homeware. The biggest charity shop near the city for furniture.", "tip": "Mon–Fri 9:30–16:30 only; take the car", "lat": 52.904375, "lon": -1.182278, "price": 0, "walk": 95, "img": "img/n134.svg", "q": "Sue Ryder Superstore, Clifton, Clifton Triangle, Green Lane, NG11 9LN, Nottingham", "ta": false, "far": true, "web": "", "drive": "15 min", "who": ["m", "w", "k"]}, {"id": "n135", "cat": "food", "name": "Small Food Bakery", "addr": "Primary, 33 Seely Road, NG7 1NU", "text": "A slow-fermentation sourdough and pastry bakery inside the Primary arts building, named one of Britain's top 50 bakeries by the Good Food Guide in January 2026.", "tip": "Thu–Sat 9:30–16:00; the custard doughnuts sell out. Pair with Primary", "lat": 52.95531, "lon": -1.1677, "price": 0, "walk": 20, "img": "img/n135.svg", "q": "Small Food Bakery, Primary, 33 Seely Road, NG7 1NU, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n136", "cat": "food", "name": "Murat Food Centre", "addr": "30–40 Bath Street, Sneinton, NG1 1DF", "text": "A big Turkish-run international supermarket with Turkish, Polish and South Asian groceries, fresh bread, olives and a halal butcher, beside Sneinton Market.", "tip": "Check it's trading at this address before a special trip", "lat": 52.9551, "lon": -1.1395, "price": 0, "walk": 12, "img": "img/n136.svg", "q": "Murat Food Centre, 30–40 Bath Street, Sneinton, NG1 1DF, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n137", "cat": "fun", "name": "Warhammer World", "addr": "Willow Road, Lenton, NG7 2WS", "text": "Games Workshop's global headquarters visitor centre: a miniatures exhibition hall, huge gaming tables, a store with exclusives, and the Bugman's Bar pub. Only in Nottingham.", "tip": "The exhibition is ticketed · late opening on Thursdays", "lat": 52.94125, "lon": -1.173514, "price": 0, "walk": 34, "img": "img/n137.svg", "q": "Warhammer World, Willow Road, Lenton, NG7 2WS, Nottingham", "ta": true, "far": true, "web": "https://warhammerworld.warhammer-community.com", "drive": "", "who": []}, {"id": "n138", "cat": "fun", "name": "NQ64", "addr": "10 Thurland Street, NG1 3DR", "text": "A retro arcade bar in the old Roxy Ballroom, with 30-plus arcade cabinets, pinball, dance mats and consoles, plus game-themed cocktails.", "tip": "Free play in the day at weekends; busy late", "lat": 52.954064, "lon": -1.146408, "price": 0, "walk": 4, "img": "img/n138.svg", "q": "NQ64, 10 Thurland Street, NG1 3DR, Nottingham", "ta": true, "far": false, "web": "https://nq64.co.uk/nottingham", "drive": "", "who": []}, {"id": "n139", "cat": "fun", "name": "National Ice Centre public skating", "addr": "Bolero Square, NG1 1LA", "text": "Public skating on an Olympic-size rink in the Lace Market, at the home of British ice skating where Torvill and Dean's Bolero is celebrated. Festive sessions run in December.", "tip": "Book sessions online", "lat": 52.952527, "lon": -1.139458, "price": 0, "walk": 11, "img": "img/n139.svg", "q": "National Ice Centre public skating, Bolero Square, NG1 1LA, Nottingham", "ta": true, "far": false, "web": "https://www.national-ice-centre.com", "drive": "", "who": []}, {"id": "n140", "cat": "fun", "name": "Winter Wonderland (seasonal)", "addr": "Old Market Square, NG1 2DT", "text": "The Christmas market fills the Old Market Square, with an ice rink, Observation Wheel and Ice Bar. Entry is free and the rides are ticketed. Runs 12 November to 31 December 2026, with stalls until 24 December.", "tip": "Weekday daytimes are far quieter", "lat": 52.953, "lon": -1.1496, "price": 0, "walk": 1, "img": "img/n140.svg", "q": "Winter Wonderland (seasonal), Old Market Square, NG1 2DT, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n141", "cat": "music", "name": "JT Soar", "addr": "2 Aberdeen Street, Sneinton, NG3 1JB", "text": "A volunteer-run DIY venue and recording studio in an old warehouse, booking touring UK and US underground punk, indie and noise bands.", "tip": "Tickets around £10 · small and informal", "lat": 52.954681, "lon": -1.136534, "price": 0, "walk": 15, "img": "img/n141.svg", "q": "JT Soar, 2 Aberdeen Street, Sneinton, NG3 1JB, Nottingham", "ta": false, "far": false, "web": "", "drive": "", "who": []}, {"id": "n142", "cat": "music", "name": "Albert Hall", "addr": "North Circus Street, NG1 5AA", "text": "A grand Victorian hall with a famous organ, used for seated gigs, touring bands, comedy and candlelit concerts.", "tip": "Balcony seats have the best sound", "lat": 52.954312, "lon": -1.156231, "price": 0, "walk": 7, "img": "img/n142.svg", "q": "Albert Hall, North Circus Street, NG1 5AA, Nottingham", "ta": true, "far": false, "web": "https://www.alberthallnottingham.co.uk", "drive": "", "who": []}, {"id": "n143", "cat": "mid", "name": "Piccalilli", "addr": "1a Cannon Court, off Long Row West, NG1 6JE", "text": "A Michelin Bib Gourmand small-plates restaurant up a staircase in a rustic old building, with a seasonal modern British menu. Excellent value for the quality.", "tip": "Thu–Sun only; book ahead", "lat": 52.9536, "lon": -1.1517, "price": 2, "walk": 2, "img": "img/n143.svg", "q": "Piccalilli, 1a Cannon Court, off Long Row West, NG1 6JE, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n144", "cat": "mid", "name": "Little Brickhouse", "addr": "110 Derby Road, NG1 5FB", "text": "A cosy neighbourhood bistro and natural-wine bar with French and Scandinavian-leaning sharing plates, picked by the Good Food Guide as a Best Local Restaurant.", "tip": "Fits neatly into a Derby Road antiques browse", "lat": 52.955661, "lon": -1.160163, "price": 2, "walk": 12, "img": "img/n144.svg", "q": "Little Brickhouse, 110 Derby Road, NG1 5FB, Nottingham", "ta": true, "far": false, "web": "https://www.littlebrickhouse.co.uk", "drive": "", "who": []}, {"id": "n145", "cat": "mid", "name": "Pici", "addr": "17 Broad Street, Hockley, NG1 3AJ", "text": "Fresh handmade pasta in a small Hockley dining room, the Good Food Guide's Italian pick for the city.", "tip": "Closed Mondays; book at weekends", "lat": 52.954395, "lon": -1.14437, "price": 2, "walk": 6, "img": "img/n145.svg", "q": "Pici, 17 Broad Street, Hockley, NG1 3AJ, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n146", "cat": "cheap", "name": "Everyday People", "addr": "12 Byard Lane, NG1 2GJ", "text": "MasterChef finalist Pete Hewitt's ramen and small-plates bar, which calls itself the city's first ramen shop.", "tip": "Go for the tonkotsu", "lat": 52.952015, "lon": -1.1464, "price": 2, "walk": 4, "img": "img/n146.svg", "q": "Everyday People, 12 Byard Lane, NG1 2GJ, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n147", "cat": "cafes", "name": "Effy", "addr": "20A Heathcoat Street, NG1 3AA", "text": "A pink, design-led specialty coffee shop with its own pastries, regularly ranked among the city's best cafés.", "tip": "Near Hockley; arrive early for the pastries", "lat": 52.954449, "lon": -1.143078, "price": 1, "walk": 8, "img": "img/n147.svg", "q": "Effy, 20A Heathcoat Street, NG1 3AA, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n148", "cat": "pubs", "name": "The Barrel Drop", "addr": "7 Hurts Yard, NG1 6JD", "text": "A tiny two-level micropub run with Magpie Brewery, with five changing cask beers and no TV or music, just conversation.", "tip": "Steep curved steps with no handrail", "lat": 52.954558, "lon": -1.15256, "price": 1, "walk": 4, "img": "img/n148.svg", "q": "The Barrel Drop, 7 Hurts Yard, NG1 6JD, Nottingham", "ta": true, "far": false, "web": "", "drive": "", "who": []}, {"id": "n149", "cat": "fashion", "name": "Universal Works", "addr": "120–122 Derby Road, NG1 5FB", "text": "The flagship of the Nottingham-born menswear label known nationally for workwear-inspired jackets and knitwear, which is hard to find in shops outside London.", "tip": "Mon–Sat 10:00–18:00", "lat": 52.958762, "lon": -1.164277, "price": 0, "walk": 19, "img": "img/n149.svg", "q": "Universal Works, 120–122 Derby Road, NG1 5FB, Nottingham", "ta": true, "far": false, "web": "https://universalworks.co.uk", "drive": "", "who": ["m"]}, {"id": "n150", "cat": "parks", "name": "Bestwood Country Park & Winding Engine House", "addr": "Bestwood Lodge Drive, Arnold, NG5 8NE", "text": "650 acres of woods and lakes around a preserved 1873 colliery winding-engine house.", "tip": "The engine house opens on Saturday mornings · free parking", "lat": 53.021562, "lon": -1.171983, "price": 0, "walk": 126, "img": "img/n150.svg", "q": "Bestwood Country Park & Winding Engine House, Bestwood Lodge Drive, Arnold, NG5 8NE, Nottingham", "ta": true, "far": true, "web": "", "drive": "20 min", "who": []}, {"id": "n151", "cat": "parks", "name": "Rushcliffe Country Park", "addr": "Mere Way, Ruddington, NG11 6JS", "text": "Former colliery land turned into meadows, woodland paths and a lake, with a lakeside café. Pairs with a Ruddington day out.", "tip": "Parking about £3", "lat": 52.884702, "lon": -1.151917, "price": 0, "walk": 124, "img": "img/n151.svg", "q": "Rushcliffe Country Park, Mere Way, Ruddington, NG11 6JS, Nottingham", "ta": true, "far": true, "web": "", "drive": "20 min", "who": []}, {"id": "n152", "cat": "trips", "name": "Calke Abbey", "addr": "Ticknall, Derbyshire, DE73 7JF", "text": "The National Trust's 'un-stately home', left as it was found after its reclusive family's decline, with tunnels, crumbling rooms and an ancient deer park.", "tip": "Christmas opening daily 27 Nov–23 Dec 2026", "lat": 52.799727, "lon": -1.455809, "price": 0, "walk": 434, "img": "img/n152.svg", "q": "Calke Abbey, Ticknall, Derbyshire, DE73 7JF, Nottingham", "ta": true, "far": true, "web": "https://www.nationaltrust.org.uk/visit/peak-district-derbyshire/calke-abbey", "drive": "35 min", "who": []}, {"id": "n153", "cat": "trips", "name": "Chatsworth", "addr": "Bakewell, Derbyshire, DE45 1PP", "text": "The Duke of Devonshire's Peak District palace, with a vast garden and a superb art collection. Christmas at Chatsworth runs 7 November 2026 to 3 January 2027, with the Christmas market until 13 December.", "tip": "Booking needed at Christmas; add Bakewell", "lat": 53.227587, "lon": -1.61139, "price": 0, "walk": 705, "img": "img/n153.svg", "q": "Chatsworth, Bakewell, Derbyshire, DE45 1PP, Nottingham", "ta": true, "far": true, "web": "https://www.chatsworth.org", "drive": "1 hr 5 min", "who": []}, {"id": "n154", "cat": "trips", "name": "Lincoln", "addr": "Castle Square, Lincoln, LN1 3AA", "text": "A hilltop cathedral city: the castle holds an original Magna Carta, the cathedral is one of England's finest, and steep Steep Hill is lined with independent shops. The cathedral holds a ticketed Christmas market on 3–5 December 2026.", "tip": "Park at the top of the hill and walk down Steep Hill", "lat": 53.23493, "lon": -0.54101, "price": 0, "walk": 834, "img": "img/n154.svg", "q": "Lincoln, Castle Square, Lincoln, LN1 3AA, Nottingham", "ta": true, "far": true, "web": "", "drive": "55 min", "who": []}], "base": {"name": "Old Market Square", "addr": "Council House, Old Market Square, NG1 2DT", "lat": 52.95327, "lon": -1.14975}};
